@startuml

class Bus {
  + line_number : int
}

class Trajectory {
  + destination : string
}

class Approval {
  + status : string
}

class Line {
  + category : string
}

class MENSO_Ticket {
  + validity_year : int
}

class Trip {
  + time : time
  + date : date
}

class Invoice {
  + amount : float
  + discount : float
}

class Customer {
  + home_address : string
  + office_address : string
  + working_hours : string
}

class MENSO_Card {
  + card_id : string
}

Bus "*" -- "1" Line : assigned to
Line "1" -- "*" Trajectory : groups
Trajectory "1" -- "*" Approval : undergoes
Trajectory "1" -- "0..1" Line : part of
Line "1" -- "*" MENSO_Ticket : assigned to
MENSO_Ticket "1" -- "1" Customer : belongs to
MENSO_Ticket "1" -- "1" MENSO_Card : uses
Trip "*" -- "1" Line : occurs on
Trip "*" -- "1" MENSO_Ticket : registered by
Trip "*" -- "1" Bus : occurs in
Customer "1" -- "*" Invoice : receives
Invoice "1" -- "*" Trip : for

@enduml

